47	class _CerneAppState extends State<CerneApp> {
48	  late final SessionRepository _sessionRepository;
49	
50	  @override
51	  void initState() {
52	    super.initState();
53	    _sessionRepository = sl<SessionRepository>();
54	    // Fire-and-forget: the outcome reaches the UI through `statusStream`
55	    // below, not through this call's return value. `restoreSession()`
56	    // already maps every internal failure to `Left`/an `unauthenticated`
57	    // emission and never throws, but swallowing any error here anyway is
58	    // cheap insurance against it otherwise surfacing as an unhandled zone
59	    // exception.
60	    unawaited(
61	      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
62	    );
63	  }
64	
65	  // `catchError`'s handler must still complete the Future with a value of
66	  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
67	  // handler would try to complete it with `null`, which isn't assignable
68	  // to that non-nullable type and would itself throw.
69	  static Either<Failure, Unit> _asUnauthenticated(
70	    Object error,
71	    StackTrace stackTrace,
72	  ) {
73	    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
74	    return left(Failure.malformedResponse(message: error.toString()));
75	  }
